-- 1776 FORGE reference seeds. NEW D1 only. NEVER run against the legacy database.
-- Every seeded legal authority points to an official primary source. Only facts that are matters of
-- public record (titles, subjects, ratification dates) are recorded; no legal text, holdings or
-- interpretation are written here. Full text should be imported from the cited source and versioned.
-- Resource links are seeded as 'unverified' until the link checker records a live response.

UPDATE resource_links SET status='unverified' WHERE status IN ('active','pending');

UPDATE resource_links SET level='federal', jurisdiction_id='us', topics='Founding documents,Archives,History',
  description='The National Archives holds the original Declaration of Independence, Constitution and Bill of Rights and publishes official transcriptions of each.',
  subpages_json='[{"label":"Declaration of Independence transcript","url":"https://www.archives.gov/founding-docs/declaration-transcript"},{"label":"Constitution transcript","url":"https://www.archives.gov/founding-docs/constitution-transcript"},{"label":"Bill of Rights transcript","url":"https://www.archives.gov/founding-docs/bill-of-rights-transcript"},{"label":"Amendments XI–XXVII","url":"https://www.archives.gov/founding-docs/amendments-11-27"}]'
  WHERE id='archives';
UPDATE resource_links SET level='federal', jurisdiction_id='us', topics='Constitutional law,Court decisions',
  description='Constitution Annotated, prepared by the Congressional Research Service, explains each clause of the Constitution and how the Supreme Court has interpreted it.' WHERE id='constitution';
UPDATE resource_links SET level='federal', jurisdiction_id='us', topics='Legislation,Congress',
  description='The official source for federal bills, resolutions, roll-call actions, committee reports and member information from the Library of Congress.' WHERE id='congress';
UPDATE resource_links SET level='federal', jurisdiction_id='us', topics='Official publications,Statutes,Regulations',
  description='The Government Publishing Office''s authenticated repository of federal publications, including the Federal Register, public laws and the Congressional Record.' WHERE id='govinfo';
UPDATE resource_links SET level='federal', jurisdiction_id='us', topics='Court decisions',
  description='Slip opinions and bound volumes released by the Supreme Court of the United States.' WHERE id='scotus';
UPDATE resource_links SET level='state', jurisdiction_id='ga', topics='Legislation,State government',
  description='Bills, votes, members, committees and session materials of the Georgia General Assembly.' WHERE id='galegis';
UPDATE resource_links SET level='state', jurisdiction_id='ga', topics='Open records,Open meetings',
  description='The Georgia Attorney General''s guidance on the Open Records Act and Open Meetings Act, including how to request records and resolve disputes.' WHERE id='gaopen';

